ROOT = pathlib.Path(__file__).resolve().parent.parent


import datetime

BASE = 1700000000


def day_of(ts):
    return datetime.datetime.fromtimestamp(ts, datetime.timezone.utc).strftime("%Y-%m-%d")


def seed(conn, rng, scale):
    nc, no = 1500 * scale, 10000 * scale
    heavy = list(range(1, 21))
    members = [(i + 1, "User%d@Example.%s" % (i, rng.choice(["org", "com"])), "name%d" % i) for i in range(nc)]
    bookings = []
    for i in range(no):
        owner = rng.choice(heavy) if rng.random() < 0.8 else rng.randrange(1, nc + 1)
        bookings.append((i + 1, owner, BASE + rng.randrange(0, 60 * 86400), rng.randrange(1, 500)))
    conn.executemany("INSERT INTO members VALUES (?, ?, ?)", members)
    conn.executemany("INSERT INTO bookings VALUES (?, ?, ?, ?)", bookings)
    return {"members": members, "bookings": bookings}


def make_params(rng, data):
    emails = {c[0]: c[1] for c in data["members"]}
    out = []
    busy = [o for o in data["bookings"] if o[1] <= 20]
    for _ in range(20):
        o = rng.choice(busy)
        e = emails[o[1]]
        out.append({"e": e.swapcase() if rng.random() < 0.5 else e.lower(), "d": day_of(o[2])})
    out.append({"e": "nobody@example.org", "d": day_of(BASE)})
    return out


def expected(data, p):
    ids = {c[0] for c in data["members"] if c[1].lower() == p["e"].lower()}
    return sorted((o[0], o[3]) for o in data["bookings"] if o[1] in ids and day_of(o[2]) == p["d"])


